style:
body{margin:0;background:#FFFFFF}
*{box-sizing:border-box}
img{max-width:100%}
summary::-webkit-details-marker{display:none}
.preview-banner{background:#111827;color:#E5E7EB;font:500 13px/1.5 'Noto Sans',sans-serif;padding:10px 16px;text-align:center;overflow-wrap:anywhere}
iframe.gmap{width:100%;height:440px;border:0;border-radius:14px;display:block;box-shadow:0 4px 16px 1px rgba(0,0,0,.10)}
@media (max-width: 860px){
  .r-cols{grid-template-columns:minmax(0,1fr)!important}
  .r-flow{flex-direction:column!important}
  .r-arrow{transform:rotate(90deg)!important}
  .r-arrowpad{padding:6px 0!important}
  .r-van{left:50%!important;right:auto!important;transform:translateX(-50%)!important;bottom:-110px!important;width:300px!important}
  .r-cardpad{padding:36px 24px 170px!important}
  .r-padb{padding-bottom:130px!important}
  nav[aria-label="Primary"]{display:none!important}
  header a[href^="tel:"]{display:none!important}
  header > div{gap:12px!important}
  aside[style*="sticky"]{position:static!important}
  iframe.gmap{height:300px}
}

